package com.mandu.reader.data

import android.net.Uri
import android.util.Base64
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import com.mandu.reader.core.PasswordRequiredException
import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File

@RunWith(AndroidJUnit4::class)
class PdfPasswordDeviceTest {
    @Test
    fun encryptedPdfRequiresCorrectPasswordOnEverySupportedApi() = runBlocking {
        val context = InstrumentationRegistry.getInstrumentation().targetContext
        val file = File.createTempFile("password-", ".pdf", context.cacheDir)
        try {
            file.writeBytes(Base64.decode(ENCRYPTED_PDF.filterNot(Char::isWhitespace), Base64.DEFAULT))
            val repository = BookRepository(context)
            val record = repository.importFile(Uri.fromFile(file))

            expectPasswordFailure { repository.open(record).close() }
            expectPasswordFailure { repository.open(record, "wrong-password").close() }
            repository.open(record, "reader-pass").use { book ->
                assertEquals(1, book.publication.units.size)
                val bitmap = book.render(0, 96)
                assertTrue(bitmap.width > 0 && bitmap.height > 0)
            }
            repository.remove(record.id)
        } finally {
            file.delete()
        }
    }

    private suspend fun expectPasswordFailure(block: suspend () -> Unit) {
        var failedCorrectly = false
        try {
            block()
        } catch (_: PasswordRequiredException) {
            failedCorrectly = true
        }
        assertTrue("expected PasswordRequiredException", failedCorrectly)
    }

    /** Original one-page red PDF generated by Ghostscript with user password reader-pass. */
    private companion object {
        const val ENCRYPTED_PDF = """
            
        """
    }
}
